#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry euclid. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section Circle_Geometry. Variable R : realType. Record point := Point { px : R; py : R }. Variable O : point. Variable r : R. Hypothesis r_pos : 0 < r. Variables A B C D E : point. Hypotheses (HA : ((px A - px O)^2 + (py A - py O)^2 = r^2)) (HB : ((px B - px O)^2 + (py B - py O)^2 = r^2)) (HC : ((px C - px O)^2 + (py C - py O)^2 = r^2)) (HD : ((px D - px O)^2 + (py D - py O)^2 = r^2)) (HE : ((px E - px O)^2 + (py E - py O)^2 = r^2)) (A_neq_B : A <> B) (B_neq_C : B <> C) (C_neq_D : C <> D) (D_neq_E : D <> E) (E_neq_A : E <> A) (B_neq_E : B <> E). Theorem circle_five_point_config : exists angle_sum : R, angle_sum = 2 * pi. Proof. Admitted. End
